const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
  // 1. Define Sakha (Yakutia) geometry - using approximate bounding box
  const sakha = ee.Geometry.Rectangle([105, 55, 165, 75]);

  // 2. Summer 2021 date range (June-August)
  const startDate = '2021-06-01';
  const endDate = '2021-08-31';

  // 3. Load MODIS burned area data
  const burnedCol = ee.ImageCollection('MODIS/006/MCD64A1')
    .filterDate(startDate, endDate)
    .filterBounds(sakha);

  const colSize = burnedCol.size().getInfo();
  console.log(`Summer 2021 burned area images: ${colSize}`);

  if (colSize === 0) {
    console.log("<answer>C1</answer>");
    return;
  }

  // 4. Create burned area mask (BurnDate > 0 indicates burned)
  const burnedSummer = burnedCol.map(img => img.select('BurnDate').gt(0));
  const totalBurned = burnedSummer.sum();

  // 5. Calculate area - each 500m pixel = 0.25 km² = 25 hectares
  const areaImg = totalBurned.multiply(ee.Image.pixelArea()).divide(10000); // Convert to hectares

  // 6. Calculate total burned area in Sakha
  const stats = areaImg.reduceRegion({
    reducer: ee.Reducer.sum(),
    geometry: sakha,
    scale: 500,
    maxPixels: 1e13
  });

  const burnedAreaHa = stats.get('BurnDate').getInfo();
  const burnedPixels = totalBurned.reduceRegion({
    reducer: ee.Reducer.sum(),
    geometry: sakha,
    scale: 500,
    maxPixels: 1e13
  }).get('BurnDate').getInfo();

  console.log(`Burned area (hectares): ${burnedAreaHa?.toFixed(0) || 'No data'}`);
  console.log(`Burned pixels: ${burnedPixels?.toFixed(0) || 'No data'}`);

  // 7. Validation and answer
  if (burnedAreaHa === null || burnedAreaHa === undefined || isNaN(burnedAreaHa)) {
    console.log("<answer>C3</answer>");
  } else if (burnedPixels === 0) {
    console.log("<answer>C2</answer>");
  } else if (burnedAreaHa >= 6000000) {
    console.log("<answer>A</answer>");
  } else {
    console.log("<answer>B</answer>");
  }
}

async function initEE() {
  await new Promise((resolve, reject) => {
    ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
  });
  await new Promise((resolve, reject) => {
    ee.initialize(null, null, resolve, reject);
  });
  await runAnalysis();
}

initEE();
